from collections import defaultdict

def tiles1(g):
    R,C = len(g), len(g[0])
    seen = [[False]*C for _ in range(R)]
    out = []
    for r in range(R):
        for c in range(C):
            if g[r][c] and not seen[r][c]:
                col = g[r][c]; st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    a,b = st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y = a+da,b+db
                        if 0<=x<R and 0<=y<C and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; st.append((x,y))
                rs=[a for a,_ in cells]; cs=[b for _,b in cells]
                out.append((min(rs),min(cs),max(rs),max(cs),col))
    return out

