        for j in range(n):
            if i==j: continue
            r1,c1 = T[i][0], T[i][1]
            r2,c2 = T[j][0], T[j][1]
            if r1>=r2 or c1>=c2: continue
            # need tiles anchored at (r1,c2) and (r2,c1)
            k1=[t for t in T if t[0]==r1 and t[1]==c2]
            k2=[t for t in T if t[0]==r2 and t[1]==c1]
            if k1 and k2:
                rects.append((i,k1[0] if False else T.index(k1[0]), j, T.index(k2[0])))
    cnt=defaultdict(int)
    for rect in rects:
        for ti in rect: cnt[ti]+=1
    return rects, cnt

